<script setup lang="ts">
import { computed, reactive, ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import { ElMessage, ElMessageBox } from 'element-plus'
import { api, errorText, loadPage } from '../api/http'
import { useAuthStore } from '../stores/auth'
import { dateTime, nonNegativeInteger, statusLabel } from '../utils/format'
import type { Row } from '../types'
const route=useRoute(),auth=useAuthStore(),resource=computed(()=>String(route.meta.resource))
const names:Record<string,string>={materials:'物料',customers:'客户',suppliers:'供应商',warehouses:'仓库'},permissions:Record<string,string>={materials:'material',customers:'customer',suppliers:'supplier',warehouses:'warehouse'}
const name=computed(()=>names[resource.value]),canWrite=computed(()=>auth.can(`master:${permissions[resource.value]}:write`)),isMaterial=computed(()=>resource.value==='materials'),isPartner=computed(()=>['customers','suppliers'].includes(resource.value))
const rows=ref<Row[]>([]),q=ref(''),enabled=ref<boolean>(),type=ref(''),page=ref(1),total=ref(0),loading=ref(false),error=ref(''),drawer=ref(false),busy=ref(false),formError=ref(''),readOnly=ref(false),selected=ref<Row|null>(null)
const form=reactive<Row>({})
async function load(){loading.value=true;error.value='';try{const data=await loadPage<Row>(`/${resource.value}`,{q:q.value||undefined,enabled:enabled.value,type:isMaterial.value?type.value||undefined:undefined,page:page.value,size:20});rows.value=data.items;total.value=Number(data.total)}catch(e){error.value=errorText(e)}finally{loading.value=false}}
async function open(row?:Row,view=false){formError.value='';readOnly.value=view;try{selected.value=row?(await api.get(`/${resource.value}/${row.id}`)).data:null;Object.assign(form,{code:'',name:'',type:'RAW_MATERIAL',unit:'件',specification:'',minStock:'0',enabled:true,contactName:'',phone:'',address:''},selected.value||{});drawer.value=true}catch(e){error.value=errorText(e)}}
function payload(data:Row){const body:Row={code:data.code.trim(),name:data.name.trim(),enabled:data.enabled};if(isMaterial.value)Object.assign(body,{type:data.type,unit:data.unit.trim(),specification:data.specification,minStock:data.minStock});else{body.address=data.address;if(isPartner.value)Object.assign(body,{contactName:data.contactName,phone:data.phone})}if(data.version!=null)body.version=data.version;return body}
async function save(){if(busy.value)return;if(!String(form.code).trim()||!String(form.name).trim()||(isMaterial.value&&(!String(form.unit).trim()||!nonNegativeInteger(form.minStock)))){formError.value='请填写编码、名称及合法单位/非负整数预警阈值';return}busy.value=true;formError.value='';try{const body=payload(form);if(selected.value)await api.put(`/${resource.value}/${selected.value.id}`,body);else{delete body.version;await api.post(`/${resource.value}`,body)}ElMessage.success('保存成功');drawer.value=false;await load()}catch(e){formError.value=errorText(e)}finally{busy.value=false}}
async function toggle(row:Row){if(busy.value)return;try{await ElMessageBox.confirm(`${row.enabled?'停用':'启用'}「${row.name}」？停用后不能用于新的业务单据，历史记录仍保留。`,'变更启用状态',{type:'warning',confirmButtonText:'确认',cancelButtonText:'取消'});busy.value=true;const current=(await api.get(`/${resource.value}/${row.id}`)).data;await api.put(`/${resource.value}/${row.id}`,payload({...current,enabled:!current.enabled}));ElMessage.success('状态已更新');await load()}catch(e){if(e!=='cancel'&&e!=='close')error.value=errorText(e)}finally{busy.value=false}}
watch(resource,()=>{q.value='';type.value='';enabled.value=undefined;page.value=1;drawer.value=false;void load()},{immediate:true})
</script>
<template><div class="page-header"><div><h1>{{name}}管理</h1></div><el-button v-if="canWrite" type="primary" @click="open()">新建{{name}}</el-button></div><section class="panel"><form class="filters" @submit.prevent="page=1;load()"><el-input v-model="q" placeholder="搜索编码或名称" aria-label="搜索编码或名称" clearable :maxlength="100"/><el-select v-if="isMaterial" v-model="type" placeholder="全部物料类型" aria-label="物料类型" clearable><el-option label="原料" value="RAW_MATERIAL"/><el-option label="成品" value="FINISHED_GOOD"/></el-select><el-select v-model="enabled" placeholder="全部启用状态" aria-label="启用状态" clearable><el-option label="启用" :value="true"/><el-option label="停用" :value="false"/></el-select><el-button native-type="submit" type="primary">查询</el-button><el-button @click="q='';enabled=undefined;type='';page=1;load()">重置</el-button></form><div v-if="error" class="error-box" role="alert">{{error}} <el-button link @click="load">重试</el-button></div><el-table :data="rows" v-loading="loading" :empty-text="`暂无${name}，可新建资料`"><el-table-column prop="code" label="编码" min-width="160"/><el-table-column prop="name" label="名称" min-width="180"/><template v-if="isMaterial"><el-table-column label="物料类型" width="100"><template #default="{row}">{{statusLabel(row.type)}}</template></el-table-column><el-table-column prop="unit" label="单位" width="80"/><el-table-column prop="specification" label="规格" min-width="160"/><el-table-column prop="minStock" label="预警阈值" width="110" align="right"/></template><template v-else-if="isPartner"><el-table-column prop="contactName" label="联系人" width="130"/><el-table-column prop="phone" label="联系电话" width="155"/></template><el-table-column v-if="!isMaterial" prop="address" label="地址" min-width="200"/><el-table-column label="状态" width="90"><template #default="{row}"><el-tag :type="row.enabled?'success':'info'" size="small">{{row.enabled?'启用':'停用'}}</el-tag></template></el-table-column><el-table-column label="操作" width="170" fixed="right"><template #default="{row}"><el-button link type="primary" @click="open(row,true)">查看</el-button><el-button v-if="canWrite" link @click="open(row)">编辑</el-button><el-button v-if="canWrite" link :disabled="busy" @click="toggle(row)">{{row.enabled?'停用':'启用'}}</el-button></template></el-table-column></el-table><div class="table-footer"><span>编码唯一 · 不直接删除引用资料</span><el-pagination v-model:current-page="page" :total="total" :page-size="20" layout="total,prev,pager,next" @current-change="load"/></div></section><el-drawer v-model="drawer" :title="`${readOnly?'查看':selected?'编辑':'新建'}${name}`" size="min(520px,100%)" destroy-on-close><el-alert v-if="formError" :title="formError" type="error" :closable="false"/><el-form label-position="top" :disabled="readOnly" @submit.prevent="save"><div class="form-grid"><el-form-item label="编码" required><el-input v-model="form.code" aria-label="编码" :maxlength="50" :disabled="!!selected&&!isMaterial"/></el-form-item><el-form-item label="名称" required><el-input v-model="form.name" aria-label="名称" :maxlength="120"/></el-form-item><template v-if="isMaterial"><el-form-item label="物料类型" required><el-select v-model="form.type" aria-label="物料类型" :disabled="!!selected"><el-option label="原料" value="RAW_MATERIAL"/><el-option label="成品" value="FINISHED_GOOD"/></el-select></el-form-item><el-form-item label="单位" required><el-input v-model="form.unit" aria-label="单位" :maxlength="10"/></el-form-item><el-form-item label="预警阈值（整数）" required><el-input v-model="form.minStock" aria-label="预警阈值" inputmode="numeric"/></el-form-item><el-form-item label="规格" class="full"><el-input v-model="form.specification" aria-label="规格" :maxlength="255"/></el-form-item><p class="section-note full">类型建立后不可改；被引用后的编码和单位不可改。库存只通过业务单据变更。</p></template><template v-else><template v-if="isPartner"><el-form-item label="联系人"><el-input v-model="form.contactName" aria-label="联系人" :maxlength="80"/></el-form-item><el-form-item label="联系电话"><el-input v-model="form.phone" aria-label="联系电话" :maxlength="40"/></el-form-item></template><el-form-item label="地址" class="full"><el-input v-model="form.address" aria-label="地址" :maxlength="255"/></el-form-item></template><el-form-item label="启用状态"><el-switch v-model="form.enabled" active-text="启用" inactive-text="停用"/></el-form-item></div><p v-if="selected" class="section-note">创建于 {{dateTime(selected.createdAt)}} · 版本 {{selected.version}}</p><div v-if="!readOnly" class="form-footer"><el-button @click="drawer=false">取消</el-button><el-button native-type="submit" type="primary" :loading="busy">保存</el-button></div></el-form></el-drawer></template>
